  const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
  static void Check(bool b,string message){if(!b)throw new Exception(message);}
  static object Get(object o,string name){return o.GetType().GetField(name,Flags).GetValue(o);}
  static object Call(object o,string name,params object[] args){return o.GetType().GetMethods(Flags).Single(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(o,args);}
  static string Content(object o){return MapLogic.Serializer().Serialize(o);}
  static TerrainPreset Preset(){var p=PresetCatalog.Default();p.Id=Guid.NewGuid().ToString("N");p.Name="Próba 092";return p;}
  static MainWindow Window(){return new MainWindow(MainWindow.CreateProjectData(8,7,"PointyTop","Próba 0.9.2",Preset()),null);}
  static void Import(MainWindow w,LibraryIcon source,bool objects){object[] args={source,objects,null};Check((bool)Call(w,"TryImportCounterpart",args),"Import: "+args[2]);}
  static void Libraries()
  {
   LibraryPaths.EnsureDirectories(AppDomain.CurrentDomain.BaseDirectory);string objectId,iconId;LibraryIcon sourceIcon,sourceObject;
   using(var w=Window()){
    var icons=(List<LibraryIcon>)Get(w,"libraryIcons");var objects=(List<ObjectTemplate>)Get(w,"libraryObjects");sourceIcon=icons[0].Copy();sourceObject=objects[0].Graphic();
    int files=Directory.GetFiles(Path.Combine(LibraryPaths.Root,"Objects"),"*.json").Length;Import(w,sourceIcon,true);objectId=MainWindow.ConvertedAssetId(sourceIcon.Id,true);var item=objects.Single(o=>o.Id==objectId);var edited=item.Copy();edited.Name="Ręcznie zmieniony odpowiednik";edited.Asset=sourceObject.Asset;object[] edit={item,edited,false,Path.GetDirectoryName(item.FilePath),null};Check((bool)Call(w,"TryChangeObjectTemplate",edit),"Object edit");
    Import(w,sourceIcon,true);Check(Directory.GetFiles(Path.Combine(LibraryPaths.Root,"Objects"),"*.json").Length==files+1&&objects.Single(o=>o.Id==objectId).Name==edited.Name&&objects.Single(o=>o.Id==objectId).Asset.Id==edited.Asset.Id,"Reimport overwrote manual edit/duplicated file");Check(((QuickSnapshot)Call(w,"CaptureQuick")).Objects.Count(i=>i==objectId)==1,"Duplicate quick object");
    Import(w,sourceObject,false);iconId=MainWindow.ConvertedAssetId(sourceObject.Id,false);int count=icons.Count;Import(w,sourceObject,false);Check(icons.Count==count&&((QuickSnapshot)Call(w,"CaptureQuick")).Icons.Count(i=>i==iconId)==1,"Duplicate icon");
    var sameName=sourceObject.Copy();sameName.Id="other-logical-source";Import(w,sameName,false);Check(icons.Any(i=>i.Id==MainWindow.ConvertedAssetId(sameName.Id,false)),"Name-only dedup");
    using(var picker=new IconPickerDialog(()=>icons,(entry,choose)=>{var b=new ResourceTileButton{Tag=entry.Id};b.Click+=(s,e)=>choose();return b;},w.BackColor)){
     picker.Show();Check(!((Button)Get(picker,"edit")).Enabled&&!((Button)Get(picker,"remove")).Enabled,"Actions enabled without selection");var list=(FlowLayoutPanel)Get(picker,"list");((Button)list.Controls[0]).PerformClick();Check(picker.Chosen==null&&picker.DialogResult!=DialogResult.OK,"Single selection used asset");((Button)picker.CancelButton).PerformClick();Check(picker.Chosen==null,"Close approved selection");
    }
   }
   using(var w=Window()){
    var icons=(List<LibraryIcon>)Get(w,"libraryIcons");var objects=(List<ObjectTemplate>)Get(w,"libraryObjects");int ni=icons.Count,no=objects.Count;Import(w,sourceIcon,true);Import(w,sourceObject,false);Check(icons.Count==ni&&objects.Count==no,"Restart duplicated counterpart");
    var target=objects.Single(o=>o.Id==objectId);Call(w,"SelectObjectTemplate",objectId);Call(w,"PlaceObject",new PointF(40,40));var map=(MapData)Get(w,"map");string instances=Content(map.Objects),presets=Content(map.Presets);byte[] old=File.ReadAllBytes(target.FilePath);File.AppendAllText(target.FilePath," ");object[] fail={target,null,false,Path.GetDirectoryName(target.FilePath),null};Check(!(bool)Call(w,"TryChangeObjectTemplate",fail)&&((QuickSnapshot)Call(w,"CaptureQuick")).Objects.Contains(objectId),"Conflict cleared quick");File.WriteAllBytes(target.FilePath,old);
    object[] remove={target,null,false,Path.GetDirectoryName(target.FilePath),null};Check((bool)Call(w,"TryChangeObjectTemplate",remove),"Remove object");Check(!File.Exists(target.FilePath)&&instances==Content(map.Objects)&&presets==Content(map.Presets),"Delete changed map/presets");Call(w,"Undo");Check(File.Exists(target.FilePath)&&((QuickSnapshot)Call(w,"CaptureQuick")).Objects.Contains(objectId),"Undo file/list");Call(w,"Redo");Check(!File.Exists(target.FilePath),"Redo file");Import(w,sourceIcon,true);Check(objects.Count(o=>o.Id==objectId)==1&&File.Exists(objects.Single(o=>o.Id==objectId).FilePath),"Recreate counterpart");
    var icon=icons.Single(i=>i.Id==iconId);var next=icon.Copy();next.Name="Edycja ikony 092";next.Asset=sourceIcon.Asset;object[] change={icon,next,false,Path.GetDirectoryName(icon.FilePath),null};Check((bool)Call(w,"TryChangeLibraryIcon",change)&&icons.Single(i=>i.Id==iconId).Asset.Id==sourceIcon.Asset.Id,"Icon edit identity/source");
   }using(var tile=new ResourceTileButton()){int uses=0;tile.UseResource=()=>uses++;object[] key={new Message(),Keys.Enter};Call(tile,"ProcessCmdKey",key);object[] click={Message.Create(IntPtr.Zero,0x203,IntPtr.Zero,IntPtr.Zero)};Call(tile,"WndProc",click);Check(uses==2,"Tile activation routing");}Console.WriteLine("libraries PASS — both directions, reload, edited counterpart, single-selection dialog, conflict and shared delete/Undo/Redo");
  }
  static void Bucket(MainWindow w,int start){Call(w,"BeginMaterialStroke",start,EditorTool.Bucket);Call(w,"VisitBucketRegion",start);Call(w,"FinishStroke");}
  static void Buckets()
  {
   using(var w=Window()){
    var map=(MapData)Get(w,"map");var p=(TerrainPreset)Call(w,"ActivePreset");var tent=p.Icons[0];var cross=p.Icons[7];foreach(var c in map.Cells)MapLogic.ApplyTerrain(c,p.Terrains[0]);foreach(var a in new[]{tent.Asset,cross.Asset})if(!map.IconAssets.Any(x=>x.Id==a.Id))map.IconAssets.Add(a);
    for(int row=0;row<7;row++){var c=map.Cells[row*8+3];c.IconId=tent.AssetId;c.IconEntryId=tent.Id;c.IconName=tent.Name;}
    string layers=Content(map.Cells.Select(c=>new{c.Terrain,c.Color,c.Fog,c.Darkness,c.Name,c.Description}));Call(w,"SelectIcon",cross.Id);
    Bucket(w,1);Check(map.Cells.Where((c,i)=>i%8<3).All(c=>c.IconEntryId==cross.Id)&&map.Cells.Where((c,i)=>i%8>3).All(c=>c.IconId==null),"Crossed occupied barrier");Bucket(w,5);Check(map.Cells.Where((c,i)=>i%8>3).All(c=>c.IconEntryId==cross.Id),"Right region missing");Bucket(w,1);Check(map.Cells.Where((c,i)=>i%8<3).All(c=>c.IconId==null)&&map.Cells[5].IconEntryId==cross.Id,"Removed both sides");Bucket(w,1);Bucket(w,3);Check(map.Cells.All(c=>c.IconEntryId==cross.Id),"Didn't replace tent region");Bucket(w,1);Check(map.Cells.All(c=>c.IconId==null),"Didn't remove united region");Call(w,"Undo");Check(map.Cells.All(c=>c.IconEntryId==cross.Id),"Undo gesture");Call(w,"Redo");Check(map.Cells.All(c=>c.IconId==null)&&layers==Content(map.Cells.Select(c=>new{c.Terrain,c.Color,c.Fog,c.Darkness,c.Name,c.Description})),"Redo or unrelated layers changed");
    for(int r=0;r<7;r++){var c=map.Cells[r*8+3];var icon=p.Icons[r%2];c.IconId=icon.AssetId;c.IconEntryId=icon.Id;c.IconName=icon.Name;}
    Bucket(w,1);Check(map.Cells.Where((c,i)=>i%8>3).All(c=>c.IconId==null),"Mixed icon barrier crossed");foreach(var c in map.Cells)c.IconId=c.IconEntryId=c.IconName=null;
    foreach(var c in map.Cells.Where((c,i)=>i%8>=6))MapLogic.ApplyTerrain(c,p.Terrains[1]);Bucket(w,1);Check(map.Cells.Where((c,i)=>i%8>=6).All(c=>c.IconId==null),"Terrain boundary ignored");
   }Console.WriteLine("bucket PASS — production gesture, complete/mixed barrier, replacement/removal, terrain bounds and Undo/Redo");
  }
  static GraphicDefinition Graphic(string path){var source=GraphicSources.Import(path);var g=new GraphicDefinition{Source=source,Name="Źródło terenu"};g.Seal();return g;}
  static string Source(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Źródło 092.png");using(var image=new Bitmap(640,320)){using(var g=Graphics.FromImage(image))g.Clear(Color.White);image.Save(path,System.Drawing.Imaging.ImageFormat.Png);}return path;}
  static void Crops()
  {
   using(var choose=new GraphicCropSaveDialog(new[]{new TerrainGraphic{Id="a",Name="Pierwsza"},new TerrainGraphic{Id="b",Name="Druga"}},"Pierwsza")){((ComboBox)Get(choose,"target")).SelectedIndex=1;Check(choose.NameForSave=="Druga","Ambiguous source overwrote another logical name");((RadioButton)Get(choose,"create")).Checked=true;Check(choose.NameForSave=="Pierwsza","New crop name lost");}
   string path=Source();byte[] original=File.ReadAllBytes(path);using(var d=new SquareImportDialog(path)){d.Show();Check(d.ClientSize==new Size(640,660),"Square dialog not compact");d.Draft.Pan(40,20,new Size(640,320),520);d.Draft.Zoom(2);d.Draft.Transform.Angle=123;double x=d.Draft.Transform.X,y=d.Draft.Transform.Y,z=d.Draft.Transform.Zoom;d.Controls.OfType<Button>().Single(b=>b.Text=="Obrót 0°").PerformClick();Check(d.Draft.Transform.Angle==0&&d.Draft.Transform.X==x&&d.Draft.Transform.Y==y&&d.Draft.Transform.Zoom==z,"Rotation reset moved/scaled crop");((Button)d.CancelButton).PerformClick();Check(d.Result==null,"Cancel created result");}Check(original.SequenceEqual(File.ReadAllBytes(path)),"Source changed");
   var graphic=Graphic(path);using(var image=IconAssets.ReadImport(path))using(var bitmap=new Bitmap(608,408)){var surface=new CropSurface(graphic,image,false){Size=new Size(608,408),Active=true};surface.DrawToBitmap(bitmap,new Rectangle(0,0,608,408));Check(bitmap.GetPixel(20,204).R>50,"Surrounding image still clipped to square");surface.Dispose();}
   LibraryPaths.EnsureDirectories(AppDomain.CurrentDomain.BaseDirectory);var p=Preset();FillRules.SetPool(p.Terrains[0],new List<FillVariant>{new FillVariant{Graphic=graphic,GraphicId=graphic.Id}});var map=MainWindow.CreateProjectData(8,7,"PointyTop","Kadr",p);MapLogic.ApplyTerrain(map.Cells[0],p.Terrains[0]);
   using(var w=new MainWindow(map,null)){
    var entries=new List<TerrainGraphic>();w.GetType().GetField("terrainGraphics",Flags).SetValue(w,entries);var entry=TerrainGraphicLibrary.Prepare(LibraryPaths.TerrainGraphics,null,"Pierwsza",graphic,entries);Call(w,"ChangeTerrainGraphic",null,entry);string before=Content(new{map.Cells,map.Presets});var changed=graphic.Copy();CropMath.Zoom(changed,false,2);CropMath.Rotate(changed,false,31);changed.Seal();
    object[] save={entry,changed,false,"Pierwsza",LibraryPaths.TerrainGraphics,null,null};Check((bool)Call(w,"TryCommitGraphicCrop",save),"Crop overwrite: "+save[6]);var overwritten=(TerrainGraphic)save[5];Check(overwritten.Id==entry.Id&&before==Content(new{map.Cells,map.Presets}),"Library crop propagated to map/palette");object[] duplicate={overwritten,changed,true,"Pierwsza",LibraryPaths.TerrainGraphics,null,null};Check(!(bool)Call(w,"TryCommitGraphicCrop",duplicate)&&entries.Count==1,"New crop auto-suffixed name");
    object[] fresh={overwritten,changed,true,"Druga",LibraryPaths.TerrainGraphics,null,null};Check((bool)Call(w,"TryCommitGraphicCrop",fresh)&&((TerrainGraphic)fresh[5]).Id!=entry.Id,"New crop missing");var bytes=File.ReadAllBytes(overwritten.Path);File.AppendAllText(overwritten.Path," ");object[] conflict={overwritten,graphic,false,"Pierwsza",LibraryPaths.TerrainGraphics,null,null};Check(!(bool)Call(w,"TryCommitGraphicCrop",conflict),"Conflict overwritten");File.WriteAllBytes(overwritten.Path,bytes);
    var active=(TerrainPreset)Call(w,"ActivePreset");var old=active.Terrains[0];var next=old.Copy();FillRules.SetPool(next,new List<FillVariant>{new FillVariant{Id=old.Variants[0].Id,Graphic=changed,GraphicId=changed.Id}});Call(w,"UpdateTerrain",old,next,false,true);Check(map.Cells[0].TextureId==graphic.Id,"Apply Off repainted");var current=((TerrainPreset)Call(w,"ActivePreset")).Terrains[0];var third=current.Copy();FillRules.SetPool(third,new List<FillVariant>{new FillVariant{Id=current.Variants[0].Id,Graphic=graphic,GraphicId=graphic.Id}});Call(w,"UpdateTerrain",current,third,true,true);Check(map.Cells[0].TextureId==graphic.Id,"Apply On wrong snapshot");Call(w,"UpdateTerrain",third,next,true,true);Check(map.Cells[0].TextureId==changed.Id,"Apply On did not update historical field");
   }
   using(var d=new AppearancePoolDialog("Nowy teren","Nazwa",Enumerable.Range(0,11).Select(i=>new FillVariant()).ToList(),false,false,"Zastosuj do bieżącej mapy")){d.Show();var tiles=(FlowLayoutPanel)Get(d,"tiles");Check(tiles.Controls[4].Top==tiles.Controls[0].Top&&tiles.Controls[4].Right<=tiles.ClientSize.Width,"Fifth column clipped");Check(tiles.Controls[9].Top==tiles.Controls[5].Top&&tiles.Controls[9].Bottom<=tiles.ClientSize.Height,"Second row clipped");d.Close();}
   Console.WriteLine("crop PASS — compact/reset/surroundings, overwrite/new/conflict, apply On/Off and 5x2");
  }
  static void Status()
  {
   LibraryPaths.EnsureDirectories(AppDomain.CurrentDomain.BaseDirectory);var p=Preset();PresetCatalog.Write(p,LibraryPaths.Presets,false);
   using(var w=new MainWindow(MainWindow.CreateProjectData(8,7,"PointyTop","Status",p),null)){
    var button=(Button)Get(w,"savePresetButton");var active=(TerrainPreset)Call(w,"ActivePreset");Call(w,"UpdatePresetStatus");Check(button.BackColor==ChoiceStyle.NeutralBack,"Clean preset accented");active.Terrains[0].Name="Draft";Call(w,"UpdatePresetStatus");Check(button.BackColor==ChoiceStyle.ActiveBack&&!(bool)Get(w,"dirty"),"Dirty preset not accented / map dirty");
    object[] save={LibraryPaths.Presets,false,active.Name,PresetSections.Icons,null};Check((bool)Call(w,"TrySaveWorkingPreset",save)&&button.BackColor==ChoiceStyle.ActiveBack,"Partial save lost omitted dirty accent");object[] restore={LibraryPaths.Presets,PresetSections.Terrains,null};Check((bool)Call(w,"TryRestorePreset",restore)&&button.BackColor==ChoiceStyle.NeutralBack,"Restore didn't clear accent");
    active=(TerrainPreset)Call(w,"ActivePreset");var other=active.Copy();other.Id=Guid.NewGuid().ToString("N");other.Name="Other unsaved draft";((MapData)Get(w,"map")).Presets.Add(other);Call(w,"RefreshPresetPicker");Check(button.BackColor==ChoiceStyle.NeutralBack,"Other draft accented current");Call(w,"SelectPreset",other.Id);Check(button.BackColor==ChoiceStyle.ActiveBack,"Unsaved current not accented");
   }Console.WriteLine("status PASS — same WorkingPresetDirty source, partial/restore/select, map independent");
  }
  static void Fixture(){LibraryPaths.EnsureDirectories(AppDomain.CurrentDomain.BaseDirectory);var p=Preset();p.Name="Preset 092";string sourcePath=Source();using(var image=new Bitmap(640,320)){using(var g=Graphics.FromImage(image)){g.Clear(Color.Transparent);using(var b=new SolidBrush(Color.FromArgb(190,170,80,40)))g.FillEllipse(b,50,20,540,280);g.DrawRectangle(Pens.White,170,70,300,180);}image.Save(sourcePath,System.Drawing.Imaging.ImageFormat.Png);}var graphic=Graphic(sourcePath);var entry=TerrainGraphicLibrary.Prepare(LibraryPaths.TerrainGraphics,null,"Grafika próby 092",graphic,new List<TerrainGraphic>());new TerrainGraphicChange{After=entry}.Write(true);var fills=Enumerable.Range(0,11).Select(i=>new FillVariant()).ToList();fills[0].Graphic=graphic;fills[0].GraphicId=graphic.Id;FillRules.SetPool(p.Terrains[0],fills);PresetCatalog.Write(p,LibraryPaths.Presets,false);var map=MainWindow.CreateProjectData(8,7,"PointyTop","Próba 0.9.2",p);foreach(var c in map.Cells)MapLogic.ApplyTerrain(c,p.Terrains[0]);for(int r=0;r<7;r++){var c=map.Cells[r*8+3];c.IconId=p.Icons[0].AssetId;c.IconEntryId=p.Icons[0].Id;c.IconName=p.Icons[0].Name;}string file=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Próba 0.9.2.hexmap");MainWindow.WriteProjectData(map,file,false);RecentProjects.Shared.Touch(file);Console.WriteLine("Fixture: "+file);}
  [STAThread]static int Main(string[] args){try{if(args.Length!=1)throw new Exception("One Case required");Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args[0]=="libraries")Libraries();else if(args[0]=="bucket")Buckets();else if(args[0]=="crop")Crops();else if(args[0]=="status")Status();else if(args[0]=="fixture")Fixture();else throw new Exception("Unknown case");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
